From 8c8bb1f389243e4369eaf47b5f7d018f4a1775bd Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Thu, 26 Nov 2026 22:36:19 +0100
Subject: [PATCH] containments/desktop: don't place new icons under widgets

New desktop icons went to the first free grid cell even when a widget
covered it, so they ended up hidden. The view now tells the positioner
which cells overlap widgets, and new icons skip those cells.

BUG: 374094
---
 .../package/contents/ui/FolderView.qml        | 35 +++++++++++
 .../package/contents/ui/FolderViewLayer.qml   | 14 +++++
 .../desktop/plugins/folder/positioner.cpp     | 59 +++++++++++++++----
 .../desktop/plugins/folder/positioner.h       |  7 +++
 4 files changed, 103 insertions(+), 12 deletions(-)

diff --git a/containments/desktop/package/contents/ui/FolderView.qml b/containments/desktop/package/contents/ui/FolderView.qml
index b858d16f7a..d602dfdef6 100644
--- a/containments/desktop/package/contents/ui/FolderView.qml
+++ b/containments/desktop/package/contents/ui/FolderView.qml
@@ -53,6 +53,8 @@ FocusScope {
     property alias scrollDown: gridView.scrollDown
     property alias hoveredItem: gridView.hoveredItem
     property alias containsMouse: listener.containsMouse
+    // Widget geometries, in view coordinates, that new icons should not be placed under
+    property list<rect> occupiedAreas: []
     property var history: []
     property var lastPosition: null
     property bool goingBack: false
@@ -1348,6 +1350,39 @@ FocusScope {
                 ? (gridView.width / gridView.cellWidth)
                 : (gridView.height / gridView.cellHeight))

+            blockedRows: {
+                if (!enabled || main.occupiedAreas.length === 0 || perStripe <= 0) {
+                    return [];
+                }
+
+                const rows = (gridView.flow === GridView.FlowLeftToRight);
+                const stripes = Math.ceil(rows ? (gridView.height / gridView.cellHeight) : (gridView.width / gridView.cellWidth));
+                const margin = Kirigami.Units.smallSpacing;
+                let blocked = [];
+
+                for (let s = 0; s < stripes; s++) {
+                    for (let i = 0; i < perStripe; i++) {
+                        let itemX = (rows ? i : s) * gridView.cellWidth;
+                        const itemY = (rows ? s : i) * gridView.cellHeight;
+
+                        if (gridView.effectiveLayoutDirection === Qt.RightToLeft) {
+                            itemX = gridView.width - itemX - gridView.cellWidth;
+                        }
+
+                        const overlaps = main.occupiedAreas.some(area => itemX + margin < area.x + area.width
+                            && itemX + gridView.cellWidth - margin > area.x
+                            && itemY + margin < area.y + area.height
+                            && itemY + gridView.cellHeight - margin > area.y);
+
+                        if (overlaps) {
+                            blocked.push((s * perStripe) + i);
+                        }
+                    }
+                }
+
+                return blocked;
+            }
+
             onModelReset: {
                 // When reset, listener.pressedItem will be invalidated.
                 listener.clearPressState();
diff --git a/containments/desktop/package/contents/ui/FolderViewLayer.qml b/containments/desktop/package/contents/ui/FolderViewLayer.qml
index 02c7491b36..ea51d02f82 100644
--- a/containments/desktop/package/contents/ui/FolderViewLayer.qml
+++ b/containments/desktop/package/contents/ui/FolderViewLayer.qml
@@ -212,6 +212,20 @@ FocusScope {
         focus: true
         isRootView: Plasmoid.isContainment
         positionerApplet: Plasmoid
+        occupiedAreas: {
+            const layout = Plasmoid.isContainment ? root.appletsLayout : null;
+            if (!layout) {
+                return [];
+            }
+
+            let areas = [];
+            for (const child of layout.children) {
+                if (child.applet && child.visible) {
+                    areas.push(folderView.view.mapFromItem(layout, child.x, child.y, child.width, child.height));
+                }
+            }
+            return areas;
+        }

         url: Plasmoid.configuration.url
         locked: (Plasmoid.configuration.locked || !Plasmoid.isContainment || folderViewLayerComponent.lockedByKiosk)
diff --git a/containments/desktop/plugins/folder/positioner.cpp b/containments/desktop/plugins/folder/positioner.cpp
index 8fc7ec4c6c..d0f8f23a5d 100644
--- a/containments/desktop/plugins/folder/positioner.cpp
+++ b/containments/desktop/plugins/folder/positioner.cpp
@@ -164,6 +164,21 @@ void Positioner::setPerStripe(int perStripe)
     }
 }

+QList<int> Positioner::blockedRows() const
+{
+    return m_blockedRows.values();
+}
+
+void Positioner::setBlockedRows(const QList<int> &blockedRows)
+{
+    const QSet<int> rows(blockedRows.cbegin(), blockedRows.cend());
+
+    if (m_blockedRows != rows) {
+        m_blockedRows = rows;
+        Q_EMIT blockedRowsChanged();
+    }
+}
+
 QStringList Positioner::positions() const
 {
     QStringList positions;
@@ -462,7 +477,7 @@ int Positioner::move(const QVariantList &moves, bool save)
             to = firstFreeRow();

             if (to == -1) {
-                to = lastRow() + 1;
+                to = firstUnblockedRow(lastRow() + 1);
             }
         }

@@ -626,7 +641,12 @@ void Positioner::sourceRowsAboutToBeInserted(const QModelIndex &parent, int star
         if (m_deferApplyPositions) {
             return;
         } else if (m_proxyToSource.isEmpty()) {
-            beginInsertRows(parent, start, end);
+            int lastNew = -1;
+            for (int i = 0; i <= end; ++i) {
+                lastNew = firstUnblockedRow(lastNew + 1);
+            }
+
+            beginInsertRows(parent, start, lastNew);
             m_beginInsertRowsCalled = true;

             initMaps(end + 1);
@@ -663,14 +683,19 @@ void Positioner::sourceRowsAboutToBeInserted(const QModelIndex &parent, int star
         }

         if (rest != -1) {
-            int firstNew = lastRow() + 1;
-            int remainder = (end - rest);
+            const int firstNew = lastRow() + 1;
+            QList<int> newRows;
+
+            for (int i = rest, row = firstNew; i <= end; ++i, ++row) {
+                row = firstUnblockedRow(row);
+                newRows.append(row);
+            }

-            beginInsertRows(parent, firstNew, firstNew + remainder);
+            beginInsertRows(parent, firstNew, newRows.constLast());
             m_beginInsertRowsCalled = true;

-            for (int i = 0; i <= remainder; ++i) {
-                updateMaps(firstNew + i, rest + i);
+            for (int i = 0; i < newRows.count(); ++i) {
+                updateMaps(newRows.at(i), rest + i);
             }
         } else {
             m_ignoreNextTransaction = true;
@@ -838,8 +863,9 @@ void Positioner::initMaps(int size)
         return;
     }

-    for (int i = 0; i < size; ++i) {
-        updateMaps(i, i);
+    for (int i = 0, row = 0; i < size; ++i, ++row) {
+        row = firstUnblockedRow(row);
+        updateMaps(row, i);
     }
 }

@@ -878,7 +904,7 @@ int Positioner::firstFreeRow() const
         int last = lastRow();

         for (int i = 0; i <= last; ++i) {
-            if (!m_proxyToSource.contains(i)) {
+            if (!m_proxyToSource.contains(i) && !m_blockedRows.contains(i)) {
                 return i;
             }
         }
@@ -887,6 +913,15 @@ int Positioner::firstFreeRow() const
     return -1;
 }

+int Positioner::firstUnblockedRow(int row) const
+{
+    while (m_blockedRows.contains(row)) {
+        ++row;
+    }
+
+    return row;
+}
+
 void Positioner::convertFolderModelData()
 {
     // Check if we need to defer
@@ -944,7 +979,7 @@ void Positioner::convertFolderModelData()
             int index = firstFreeRow();

             if (index == -1) {
-                index = lastRow() + 1;
+                index = firstUnblockedRow(lastRow() + 1);
             }

             updateMaps(index, sourceIndex);
@@ -960,7 +995,7 @@ void Positioner::convertFolderModelData()
         int index = firstFreeRow();

         if (index == -1) {
-            index = lastRow() + 1;
+            index = firstUnblockedRow(lastRow() + 1);
         }

         updateMaps(index, it.value());
